input.command:
cd /home/user/myproject && mkdir -p scripts resources/enemies scenes && cat <<'EOF'> scripts/EnemyStats.gd
extends Resource
class_name EnemyStats

@export var name: String
@export var max_health: int
@export var speed: float
@export var damage: int
@export var color: Color
EOF
echo "Done"

cd /home/user/myproject && cat <<'EOF'> scripts/Enemy.gd
extends CharacterBody2D

@export var stats: EnemyStats
var current_health: int

@onready var color_rect = $ColorRect

func _ready() -> void:
	if stats:
		current_health = stats.max_health
		color_rect.color = stats.color

func take_damage(amount: int) -> void:
	current_health -= amount
	if current_health <= 0:
		queue_free()
EOF
echo "Done"

cd /home/user/myproject && cat <<'EOF'> scripts/Spawner.gd
extends Node2D

@export var enemy_types: Array[EnemyStats]
var enemy_scene = preload("res://scenes/Enemy.tscn")

func _ready() -> void:
	spawn_enemies()

func spawn_enemies() -> void:
	for i in range(enemy_types.size()):
		var stats = enemy_types[i]
		var enemy = enemy_scene.instantiate()
		enemy.stats = stats
		add_child(enemy)
		enemy.position = Vector2(i * 100, 0)

func take_damage_all(amount: int) -> void:
	for enemy in get_children():
		if enemy.has_method("take_damage"):
			enemy.take_damage(amount)
EOF
echo "Done"

